 			} else {
 				faissManager, err := icme.NewFAISSIndexManager(dbManager, logger)
 				if err != nil {
 					log.Printf("Warning: Failed to initialize ICME FAISS manager: %v", err)
 				} else {
 					graphEngine := icme.NewTemporalHypergraph(
 						icmeConfig.GraphWindowSize,
