package payment

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/stripe/stripe-go/v76/webhook"
)

// WebhookEvent represents a Stripe webhook event
type WebhookEvent struct {
	ID      string      `json:"id"`
	Type    string      `json:"type"`
	Data    WebhookData `json:"data"`
	Created int64       `json:"created"`
	Livemode bool        `json:"livemode"`
}

// WebhookData contains the event data
type WebhookData struct {
	Object json.RawMessage `json:"object"`
}

// StripeWebhookHandler processes incoming Stripe webhooks with signature verification
func (ss *StripeService) HandleWebhook(w http.ResponseWriter, r *http.Request) {
	const MaxBodyBytes = int64(65536)
	r.Body = http.MaxBytesReader(w, r.Body, MaxBodyBytes)

	payload, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Error reading request body", http.StatusBadRequest)
		return
	}

	stripeSignature := r.Header.Get("Stripe-Signature")
	if stripeSignature == "" {
		http.Error(w, "Missing Stripe-Signature header", http.StatusBadRequest)
		return
	}

	// Validate webhook signature using Stripe's official library
	event, err := webhook.ConstructEvent(payload, stripeSignature, ss.webhookSecret)
	if err != nil {
		http.Error(w, fmt.Sprintf("Webhook signature verification failed: %v", err), http.StatusBadRequest)
		return
	}

	// Process the event based on type
	switch event.Type {
	case "payment_intent.succeeded":
		var paymentIntent map[string]interface{}
		if err := json.Unmarshal(event.Data.Raw, &paymentIntent); err != nil {
			http.Error(w, "Error parsing payment intent", http.StatusBadRequest)
			return
		}
		ss.handlePaymentSucceeded(paymentIntent)

	case "payment_intent.payment_failed":
		var paymentIntent map[string]interface{}
		if err := json.Unmarshal(event.Data.Raw, &paymentIntent); err != nil {
			http.Error(w, "Error parsing payment intent", http.StatusBadRequest)
			return
		}
		ss.handlePaymentFailed(paymentIntent)

	case "charge.succeeded":
		var charge map[string]interface{}
		if err := json.Unmarshal(event.Data.Raw, &charge); err != nil {
			http.Error(w, "Error parsing charge", http.StatusBadRequest)
			return
		}
		ss.handleChargeSucceeded(charge)

	case "charge.failed":
		var charge map[string]interface{}
		if err := json.Unmarshal(event.Data.Raw, &charge); err != nil {
			http.Error(w, "Error parsing charge", http.StatusBadRequest)
			return
		}
		ss.handleChargeFailed(charge)

	case "customer.subscription.created",
		"customer.subscription.updated",
		"customer.subscription.deleted":
		var subscription map[string]interface{}
		if err := json.Unmarshal(event.Data.Raw, &subscription); err != nil {
			http.Error(w, "Error parsing subscription", http.StatusBadRequest)
			return
		}
		ss.handleSubscriptionChange(event.Type, subscription)

	default:
		// Unexpected event type
		fmt.Printf("Unhandled webhook event type: %s\n", event.Type)
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "ok", "event_id": event.ID})
}

// handlePaymentSucceeded processes a successful payment intent
func (ss *StripeService) handlePaymentSucceeded(paymentIntent map[string]interface{}) {
	fmt.Printf("Payment succeeded: %v\n", paymentIntent["id"])

	// Extract relevant data
	rentalID, _ := paymentIntent["metadata"].(map[string]interface{})["rental_id"].(string)
	if rentalID != "" {
		// Update rental status in database
		// Provision DVE resources
		// Send confirmation email
		fmt.Printf("Updating rental %s to active\n", rentalID)
	}
}

// handlePaymentFailed processes a failed payment intent
func (ss *StripeService) handlePaymentFailed(paymentIntent map[string]interface{}) {
	fmt.Printf("Payment failed: %v\n", paymentIntent["id"])

	rentalID, _ := paymentIntent["metadata"].(map[string]interface{})["rental_id"].(string)
	if rentalID != "" {
		// Update rental status to failed
		// Notify user
		fmt.Printf("Marking rental %s as failed\n", rentalID)
	}
}

// handleChargeSucceeded processes a successful charge
func (ss *StripeService) handleChargeSucceeded(charge map[string]interface{}) {
	fmt.Printf("Charge succeeded: %v\n", charge["id"])
}

// handleChargeFailed processes a failed charge
func (ss *StripeService) handleChargeFailed(charge map[string]interface{}) {
	fmt.Printf("Charge failed: %v\n", charge["id"])
}

// handleSubscriptionChange processes subscription changes
func (ss *StripeService) handleSubscriptionChange(eventType string, subscription map[string]interface{}) {
	fmt.Printf("Subscription %s: %v\n", eventType, subscription["id"])
}

// ValidateWebhookSignature validates a Stripe webhook signature without using stripe-go library
// This is an alternative implementation for environments where stripe-go is not available
func (ss *StripeService) ValidateWebhookSignature(payload []byte, signature string) error {
	if ss.webhookSecret == "" {
		return fmt.Errorf("webhook secret not configured")
	}

	// Parse the Stripe-Signature header
	// Format: t=timestamp,v1=signature,v0=signature
	parts := strings.Split(signature, ",")
	var timestamp string
	var signatures []string

	for _, part := range parts {
		part = strings.TrimSpace(part)
		if strings.HasPrefix(part, "t=") {
			timestamp = strings.TrimPrefix(part, "t=")
		} else if strings.HasPrefix(part, "v1=") {
			signatures = append(signatures, strings.TrimPrefix(part, "v1="))
		}
	}

	if timestamp == "" || len(signatures) == 0 {
		return fmt.Errorf("invalid signature format")
	}

	// Check timestamp to prevent replay attacks (within 5 minutes)
	if ts, err := time.Parse(time.UnixDate, timestamp); err == nil {
		if time.Since(ts) > 5*time.Minute {
			return fmt.Errorf("webhook timestamp too old")
		}
	}

	// Compute expected signature
	// Stripe uses: HMAC_SHA256(webhook_secret, timestamp + "." + payload)
	expectedMAC := hmac.New(sha256.New, []byte(ss.webhookSecret))
	expectedMAC.Write([]byte(timestamp))
	expectedMAC.Write([]byte("."))
	expectedMAC.Write(payload)
	expectedSignature := fmt.Sprintf("%x", expectedMAC.Sum(nil))

	// Compare signatures
	for _, sig := range signatures {
		if hmac.Equal([]byte(sig), []byte(expectedSignature)) {
			return nil
		}
	}

	return fmt.Errorf("signature mismatch")
}

package payment

import (
	"crypto"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

// PayPalWebhookEvent represents a PayPal webhook event
type PayPalWebhookEvent struct {
	ID          string                 `json:"id"`
	EventType   string                 `json:"event_type"`
	ResourceType string                 `json:"resource_type"`
	Resource    map[string]interface{} `json:"resource"`
	Summary     string                 `json:"summary"`
	CreateTime  string                 `json:"create_time"`
	WebhookID  string                 `json:"webhook_id"`
}

// PayPalWebhookHandler processes incoming PayPal webhooks with signature verification
func (ps *PayPalService) HandleWebhook(w http.ResponseWriter, r *http.Request) {
	// Read body
	payload, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Error reading request body", http.StatusBadRequest)
		return
	}

	// Verify PayPal webhook signature
	if err := ps.verifyPayPalSignature(r, payload); err != nil {
		http.Error(w, fmt.Sprintf("Webhook signature verification failed: %v", err), http.StatusBadRequest)
		return
	}

	// Parse event
	var event PayPalWebhookEvent
	if err := json.Unmarshal(payload, &event); err != nil {
		http.Error(w, "Error parsing webhook event", http.StatusBadRequest)
		return
	}

	// Process event
