 	if s.dveCreationService != nil {
 		if err := s.dveCreationService.Start(); err != nil {
 			log.Printf("Warning: Failed to start DVE creation service: %v", err)
 		} else {
 			log.Println("DVE Creation Service started")
 		}
 	}

