 	resp, err := c.client.ValidateSession(ctx, &pb.ValidateSessionRequest{SessionId: sessionID})
 	if err != nil {
 		return nil, fmt.Errorf("failed to validate session: %w", err)
 	}
 	if !resp.Valid {
 		return nil, fmt.Errorf("session is not valid: %s", sessionID)
 	}

